insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$bebedouro$q$, $q$https://bebedouro.siscam.com.br/arquivo?Id=33274 (Dec. 11.503/2015, DO eletrônico ed. 479, 05/05/2015) ; https://bebedouro.siscam.com.br/arquivo?Id=30935 (Lei 4.887/2014) ; https://bebedouro.siscam.com.br/arquivo?Id=28659 e https://bebedouro.siscam.com.br/arquivo?Id=29739 (Leis 2.675/1997 e 3.720/2007)$q$, $q$Atos oficiais de Bebedouro: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: polígono pelos cruzamentos das vias-limite no OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 1, $q$Dec. 11.503/2015 (regulamenta a Lei 4.887/2014): no interior do quadrilátero R. Campos Sales / R. Vanor Junqueira Franco / R. Brandão Veras / R. N. Sra. de Fátima (vias-limite livres), caminhão com comprimento acima de 6,30 m ou largura acima de 2,20 m proibido seg–sex 9h–18h e sáb 9h–14h, exceto feriados e domingos sem comércio. Desativadas: Zona Azul 6,30–12 m (Lei 4.887, art. 3º: redação permissiva e área não conferida) e cana/vinhaça no perímetro urbano (critério de carga).$q$);
